/* Utility Menu UI - Modernized */
.vnpt-util-dropdown { position: relative; }
.vnpt-util-menu {
    position: absolute; top: calc(100% + 10px); right: 0;
    background: #fff; border: 1px solid var(--vnpt-border); border-radius: 16px;
    box-shadow: 0 12px 32px rgba(0,0,0,0.15); z-index: 100000;
    display: none; flex-direction: column; width: 280px;
    padding: 8px;
    transform-origin: top right;
    animation: menuFadeIn 0.2s cubic-bezier(0.165, 0.84, 0.44, 1);
}
.vnpt-util-menu.show { display: flex; }

@keyframes menuFadeIn {
    from { opacity: 0; transform: translateY(-8px) scale(0.95); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

.util-config-container { display: flex; flex-direction: column; gap: 4px; }

.util-section-mini {
    padding: 6px 4px; border-bottom: 1px solid rgba(0,0,0,0.04);
}
.util-section-mini:last-child { border-bottom: none; }

.util-action-row { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }

.util-item-mini {
    background: #f8f9fa; border: 1px solid transparent; border-radius: 8px;
    padding: 6px 8px; font-size: 11px; font-weight: 600; color: #3c4043;
    cursor: pointer; transition: all 0.2s; text-align: left;
    display: flex; align-items: center; gap: 8px;
}
.util-item-mini:hover { background: var(--vnpt-primary-light); color: var(--vnpt-primary); transform: translateY(-1px); }
.util-item-mini.danger:hover { background: #fdf2f2; color: #d93025; }

.util-row-compact { display: flex; align-items: center; justify-content: space-between; padding: 4px; }
.util-label-tiny { font-size: 10px; font-weight: 800; color: #9aa0a6; text-transform: uppercase; letter-spacing: 0.5px; }

.size-options-tiny { display: flex; gap: 4px; }
.size-options-tiny button {
    padding: 4px 8px; border: 1px solid #eee; border-radius: 6px;
    background: #fff; font-size: 10px; font-weight: 700; cursor: pointer;
    transition: all 0.2s;
}
.size-options-tiny button:hover { border-color: var(--vnpt-primary); color: var(--vnpt-primary); background: var(--vnpt-primary-light); }

.cw-row-mini { display: flex; gap: 6px; }
.cw-input-mini {
    flex: 1; padding: 6px 10px; border: 1px solid #eee; border-radius: 8px;
    font-size: 11px; background: #f8f9fa; transition: all 0.2s;
}
.cw-input-mini:focus { border-color: var(--vnpt-primary); outline: none; background: #fff; box-shadow: 0 0 0 3px rgba(26,115,232,0.1); }

.util-btn-test-tiny {
    background: var(--vnpt-primary); color: white; border: none;
    border-radius: 8px; width: 32px; cursor: pointer; font-size: 12px;
    transition: all 0.2s;
}
.util-btn-test-tiny:hover { transform: scale(1.1); filter: brightness(1.1); }

.vnpt-hotkey-list-mini { 
    display: flex; flex-direction: column; gap: 4px; 
    max-height: 140px; overflow-y: auto; padding-right: 4px;
}
.vnpt-hotkey-row {
    display: flex; align-items: center; justify-content: space-between;
    padding: 4px 8px; background: #f8f9fa; border-radius: 8px;
    transition: background 0.2s;
}
.vnpt-hotkey-row:hover { background: #f1f3f4; }
.vnpt-hotkey-label { font-size: 10px; color: #5f6368; font-weight: 500; }
.vnpt-hotkey-btn {
    background: #fff; border: 1px solid #eee; border-radius: 6px;
    padding: 2px 8px; font-size: 10px; font-weight: 700; color: var(--vnpt-primary);
    min-width: 60px; text-align: center; cursor: pointer; transition: all 0.2s;
}
.vnpt-hotkey-btn:hover { border-color: var(--vnpt-primary); background: var(--vnpt-primary-light); }
.vnpt-hotkey-btn.recording { animation: pulse 1s infinite; background: #fff1f0; border-color: #ea4335; color: #ea4335; }

