    --vnpt-danger: #d93025;
    --vnpt-danger-hover: #b22a1d;
    --vnpt-success: #1e8e3e;

    /* Backgrounds */
    --vnpt-bg-main: #ffffff;
    --vnpt-bg-sub: #f8f9fa;
    --vnpt-bg-input: #f1f3f4;

