edits.newText:
/* --- Base Input Style --- */
.vnpt-input-base {
    height: 26px;
    padding: 4px 10px;
    border-radius: var(--vnpt-radius);
    border: 1px solid var(--vnpt-border);
    background: var(--vnpt-bg-input);
    font-size: 11px;
    font-family: inherit;
    color: #3c4043;
    box-sizing: border-box;
    transition: all 0.2s;
}
.vnpt-input-base:hover { background: rgba(0,0,0,0.05); }
.vnpt-input-base:focus { 
    border-color: var(--vnpt-primary); 
    background: #fff; 
    box-shadow: 0 0 0 3px var(--vnpt-primary-light);
    outline: none;
}

/* --- Base Button Style --- */
.vnpt-btn-base {
    height: 26px;
    padding: 0 12px;
    border-radius: var(--vnpt-radius);
    border: 1px solid transparent;
    font-size: 11px;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    transition: all 0.2s;
    white-space: nowrap;
    user-select: none;
}
.vnpt-btn-base:hover { transform: translateY(-1px); }
.vnpt-btn-base:active { transform: translateY(0) scale(0.98); }

.vnpt-btn-primary { background: var(--vnpt-primary-grad); color: white; border: none; }
.vnpt-btn-secondary { background: var(--vnpt-bg-sub); color: #5f6368; border: 1px solid var(--vnpt-border); }
.vnpt-btn-secondary:hover { background: var(--vnpt-primary-light); color: var(--vnpt-primary); border-color: var(--vnpt-primary); }

