    /* Column splitter */
    .fields-col-splitter {
        flex: 0 0 6px; cursor: col-resize;
        display: flex; align-items: center; justify-content: center;
        background: transparent; border-radius: 3px;
        opacity: 0; transition: opacity 0.2s, background 0.2s;
        position: relative; z-index: 2;
    }
    .fields-col-splitter::after {
        content: ''; display: block;
        width: 2px; height: 60%; min-height: 10px;
        background: var(--vnpt-border); border-radius: 2px;
        transition: background 0.2s;
    }
    #vnpt-fields-container:hover .fields-col-splitter { opacity: 1; }
    .fields-col-splitter:hover::after,
    .fields-col-splitter.dragging::after { background: var(--vnpt-primary); }
    .fields-col-splitter.dragging { opacity: 1; cursor: col-resize; }

    .vnpt-field-row { 
        display: flex; gap: 4px; margin-bottom: 0px; align-items: center; 
        padding: 2px 4px; border-radius: 4px; transition: all 0.2s;
        background: transparent; border-bottom: 1px solid rgba(0,0,0,0.02);
    }
    
    /* Đảm bảo các thành phần trong hàng có kích thước cố định để thẳng hàng */
    .row-chk { flex: 0 0 14px !important; }
    .connection-badge { flex: 0 0 10px !important; }
    .btn-sync-dir, .btn-sync-dir-calc { flex: 0 0 18px !important; }
    .btn-field-link { flex: 0 0 18px !important; }
    
    .vnpt-field-row input.f-label { 
        flex: 0 0 100px; /* Thu nhỏ label một chút để tiết kiệm chỗ */
        color: var(--vnpt-primary); 
        font-weight: 600; 
        font-size: 10.5px;
        background: transparent;
        border: none !important;
        text-overflow: ellipsis;
        white-space: nowrap;
        overflow: hidden;
    }

    .vnpt-field-row input.f-value { 
        flex: 1; /* Giá trị chiếm không gian còn lại */
    }

    .vnpt-field-row .row-actions {
        display: flex;
        gap: 4px;
        flex: 0 0 auto;
        min-width: 60px;
        justify-content: flex-end;
    }

    .btn-sync-dir, .btn-sync-dir-calc {
        cursor: pointer; padding: 0; user-select: none;
        flex: 0 0 16px; height: 16px; display: flex; align-items: center; justify-content: center;
        border: none; background: transparent; color: #bdc1c6;
        transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        opacity: 0.8;
    }
    .btn-sync-dir:hover, .btn-sync-dir-calc:hover { 
        transform: scale(1.15); opacity: 1;
        background: rgba(0,0,0,0.03); border-radius: 3px;
    }
    .btn-sync-dir:active, .btn-sync-dir-calc:active { transform: scale(0.9); }
    
    .btn-sync-dir[data-dir="both"], .btn-sync-dir-calc[data-dir="both"] { color: var(--vnpt-primary); }
    .btn-sync-dir[data-dir="up"], .btn-sync-dir-calc[data-dir="up"] { color: #f57c00; }
    .btn-sync-dir[data-dir="down"], .btn-sync-dir-calc[data-dir="down"] { color: var(--vnpt-success); }
    
    .btn-sync-dir svg, .btn-sync-dir-calc svg { transition: transform 0.3s ease; width: 12px; height: 12px; }
    .btn-sync-dir:active svg, .btn-sync-dir-calc:active svg { transform: rotate(180deg); }

    .vnpt-field-row input { 
        flex: 1; padding: 2px 8px; border: 1px solid transparent; border-radius: 4px; 
        font-size: 10.5px; height: 22px; transition: all 0.2s; background: rgba(0,0,0,0.03);
        color: #3c4043; box-sizing: border-box;
    }
    .vnpt-field-row input:hover { background: rgba(0,0,0,0.06); }
    .vnpt-field-row input:focus { 
        border-color: var(--vnpt-primary); 
        box-shadow: 0 0 0 3px var(--vnpt-primary-light); 
        outline: none; background: #fff; 
    }
    
    .vnpt-field-row input.row-chk { flex: 0 0 14px; width: 12px; height: 12px; margin: 0; cursor: pointer; accent-color: var(--vnpt-primary); opacity: 0.6; }
    .vnpt-field-row input.row-chk:checked { opacity: 1; }
    .vnpt-field-row input.f-label { flex: var(--label-flex); color: var(--vnpt-primary); font-weight: 600; background: transparent; }
    .vnpt-field-row:hover input.f-label { color: var(--vnpt-primary-hover); }
    .vnpt-field-row input.f-key { display: none; flex: 0.45; font-weight: 600; color: #d63384; background: rgba(214,51,132,0.05); border-radius: 4px; font-family: monospace; font-size: 10px; }
    .show-ids .vnpt-field-row input.f-key { display: block; }

    .btn-field-link {
        cursor: pointer; padding: 0; user-select: none;
