export const fieldsStyles = `
    /* ═══════════════════════════════════════════
       SECTION 3: FIELDS CONTAINER & FIELD ROWS
       ═══════════════════════════════════════════ */
    #vnpt-fields-container { 
        flex: 1; overflow: hidden; background: #f1f3f4; 
        border: 1px solid var(--vnpt-border); border-radius: 12px; 
        margin-bottom: 4px; position: relative; display: flex; flex-direction: column; 
        box-shadow: inset 0 1px 4px rgba(0,0,0,0.08);
    }

    #vnpt-fields-list { flex: 1; overflow-y: auto; padding: 4px; }

    .vnpt-field-row { 
        display: flex; gap: 6px; margin-bottom: 1px; align-items: center; 
        padding: 4px 6px; border-radius: 6px; transition: all 0.2s;
        background: transparent; border-bottom: 1px solid rgba(0,0,0,0.03);
    }
    .vnpt-field-row:hover { 
        background: rgba(255, 255, 255, 0.8); 
        box-shadow: 0 2px 8px rgba(0,0,0,0.05); 
    }

    /* Fixed widths for alignment */
    .vnpt-field-row .row-chk { flex: 0 0 16px !important; width: 14px; height: 14px; margin: 0; cursor: pointer; accent-color: var(--vnpt-primary); opacity: 0.7; }
    .vnpt-field-row .connection-badge { flex: 0 0 12px !important; font-size: 8px; text-align: center; opacity: 0.6; }
    .vnpt-field-row .btn-sync-dir, 
    .vnpt-field-row .btn-sync-dir-calc { flex: 0 0 20px !important; border: none; background: transparent; cursor: pointer; color: #bdc1c6; display: flex; align-items: center; justify-content: center; }
    .vnpt-field-row .btn-field-link { flex: 0 0 20px !important; border: none; background: transparent; cursor: pointer; color: #bdc1c6; display: flex; align-items: center; justify-content: center; font-size: 10px; }

    /* Label with fixed width for perfect vertical alignment */
    .vnpt-field-row input.f-label { 
        flex: 0 0 110px !important; 
        color: var(--vnpt-primary); 
        font-weight: 700; 
        font-size: 11px;
        background: transparent !important;
        border: none !important;
        text-overflow: ellipsis;
        white-space: nowrap;
        overflow: hidden;
        padding: 0 4px !important;
    }

    /* ID/Key hidden by default, shown when .show-ids class is present */
    .vnpt-field-row input.f-key { 
        display: none; 
        flex: 0 0 80px; 
        font-weight: 600; 
        color: #d63384; 
        background: rgba(214,51,132,0.05) !important; 
        border-radius: 4px; 
        font-family: monospace; 
        font-size: 10px;
        border: none !important;
        margin-right: 4px;
        padding: 0 4px !important;
    }
    .show-ids .vnpt-field-row input.f-key { display: block; }

    /* Main Value Input */
    .vnpt-field-row input.f-value { 
        flex: 1; 
        padding: 4px 10px; 
        border: 1px solid transparent; 
        border-radius: 6px; 
        font-size: 11px; 
        height: 26px; 
        transition: all 0.2s; 
        background: #fff;
        color: #3c4043; 
        box-sizing: border-box;
        box-shadow: 0 1px 2px rgba(0,0,0,0.05);
    }
    .vnpt-field-row input.f-value:hover { background: #fafafa; border-color: rgba(0,0,0,0.1); }
    .vnpt-field-row input.f-value:focus { 
        border-color: var(--vnpt-primary); 
        box-shadow: 0 0 0 3px var(--vnpt-primary-light); 
        outline: none; 
        background: #fff; 
    }

    /* Actions */
    .vnpt-field-row .row-actions {
        display: flex;
        gap: 4px;
        flex: 0 0 auto;
        justify-content: flex-end;
        margin-left: 4px;
    }

    .vnpt-btn-row-action {
        background: #f1f3f4; border: none; border-radius: 4px; font-size: 10px; cursor: pointer; padding: 2px 6px; color: #5f6368; font-weight: 600;
    }
    .vnpt-btn-row-action:hover { background: #e8eaed; color: #3c4043; }
    .vnpt-btn-row-action.danger { color: var(--vnpt-danger); background: #fce8e6; }
    .vnpt-btn-row-action.danger:hover { background: #f9d7d1; }

    /* Scrollbar */
    #vnpt-fields-list::-webkit-scrollbar { width: 6px; }
    #vnpt-fields-list::-webkit-scrollbar-track { background: transparent; }
    #vnpt-fields-list::-webkit-scrollbar-thumb { background: #dadce0; border-radius: 10px; }
    #vnpt-fields-list::-webkit-scrollbar-thumb:hover { background: #bdc1c6; }

    .text-hint { font-size: 11px; color: #70757a; font-style: italic; text-align: center; margin: 20px 0; }
`;

